"""Одна прямо порученная запись: проверенная связка с MASA и границы объяснения."""
from pathlib import Path
import json
TITLE='Б1.3 — Сшивать обрывки по внешнему виду — признаки MASA'
PATH='Гипотезы — подходы/'+TITLE

def build(vault,parent,ref,fm):
    root=Path(__file__).resolve().parents[1]
    source='runs/z13_val20_matched_20261024/native_masa_recovery2/report.json'
    report=json.loads((root/source).read_text(encoding='utf-8-sig'))
    a=report['pooled']['xywh_raw'];b=report['pooled']['xywh_masa'];pair=report['paired']['xywh_masa-xywh_raw']
    assert pair['ci95'][0]>0
    num=lambda x:f'{x:.3f}'.replace('.',',')
    body=f'# {TITLE}\n\n↑ [[{parent}|Б1 — сильная база и временная поправка]]\n\n'
    body+='**Проверенная связка:** наш сшиватель обрывков с признаками MASA дал положительный результат на двадцати общих видео. Это не подтверждение Б1 и не воспроизведение полной авторской MASA.\n\n'
    body+='## Что именно проверено\n\n'
    body+='После обработки последовательности объединяли непересекающиеся обрывки траекторий. Вероятность связи оценивала замороженная логистическая регрессия по геометрии, миниатюре, гистограмме, входу глаза и признаку MASA. Это обработка готовых обрывков, а не новое назначение в каждом текущем кадре.\n\n'
    body+='Совокупная HOTA: '+num(a['HOTA'])+' → '+num(b['HOTA'])+'. Средняя парная разность по видео: +'+num(pair['mean_per_video'])+' п.п., интервал ['+num(pair['ci95'][0])+'; '+num(pair['ci95'][1])+']. Лучше на '+str(pair['better'])+' из '+str(pair['n'])+' видео.\n\n'
    body+='Смены идентификатора: '+str(int(a['IDSw']))+' → '+str(int(b['IDSw']))+'. Ложные обнаружения и пропуски в этом сравнении не изменились. Данные исторически использовались в проекте; это не независимый итоговый тест.\n\n'
    body+='## Почему получена прибавка\n\n'
    body+='Проверка сохранённых файлов подтвердила на всех двадцати видео: кадры, рамки, классы, баллы и число объектов одинаковы; меняются только идентификаторы. Улучшилась точность связывания AssA: '+num(a['AssA'])+' → '+num(b['AssA'])+'. Измеренный источник прибавки — объединение части разорванных траекторий. Это результат всей связки.\n\n'
    diagnostic=root/'runs/recovery_research_20261027/masa_feature_contribution/independent_audit.json'
    if diagnostic.exists() and json.loads(diagnostic.read_text(encoding='utf-8'))['passed']:
        body+='**В данной фиксированной голове вклад проверен:** при нейтральном MASA-признаке не принято ни одной связи и HOTA вернулась к 57,901. С правильным признаком HOTA58,486; средняя парная добавка +0,700п.п.[0,357;1,071]. Три перестановки только этого признака дали HOTA57,240/57,349/57,489, и полная версия лучше каждой с положительным интервалом. Другие признаки,порог и голова сохранялись.\n\n'
        body+='**Граница вывода:** отключить вход готовой головы не то же самое,что заново обучить хорошую голову без этого входа. В прежнем раздельно обученном сравнении на35test обычная сшивка дала +0,635п.п.кбазе,а добавкаMASAнадней+0,030[−0,228;0,298] не подтверждена. Значит,правильные признакиMASA важны для нынешнего решения,но единственным способом получить такую прибавку они не доказаны. Эти35test и нынешние20val — разные наборы.\n\n'
        body+='[Полная проверка одного признака]('+(root/'runs/recovery_research_20261027/masa_feature_contribution/report.json').as_uri()+').\n\n'
    else:
        body+='**Пока не отделено:** какая часть эффекта требует именно признака MASA,а какая достигается другими признаками. Проверка одного входа готовой головы сама по себе не заменяет отдельное переобучение безMASA.\n\n'
    body+='## Роль для Б1\n\n'
    body+='Полезный существующий компонент и сильный контроль. Б1 должна проверить дополнительную временную поправку FlyVis сверх согласованной базы. При сравнении учитывать доступ к будущему: готовая сшивка и текущие назначения используют разные временные условия. Ядро FlyVis в проверенной связке не использовалось.\n\n'
    body+='## Другая попытка — текущие назначения\n\n'
    body+='Новая плотная интеграция MASA внутрь текущего сопоставления остановлена после первого полного видео по стоимости и на обычной, и на смешанной числовой точности. Полной HOTA этой версии нет. Это отдельное применение; оно не отменяет положительный результат готовой сшивки. Возобновлять плотные прогоны ради этой записи не требуется.\n\n'
    body+='## Источники и переходы без внешних лучей\n\n'
    body+=ref('','Опорные задачи/Задача 1 — Получить сопоставимый базис для проверки новых модулей','Опыт с одинаковыми трекерами и MASA — результаты и объяснение')+'\n\n'
    body+='[Первичный отчёт]('+(root/source).as_uri()+').\n\n'
    body+='[Проверка сохранённых выходов]('+(root/'runs/recovery_research_20261027/masa_saved_explanation/report.json').as_uri()+').\n\n'
    body+='[Первичная работа MASA](https://arxiv.org/abs/2406.04221). Статья описывает метод авторов; её результаты не заменяют наши измерения.\n'
    vault.write(PATH+'.md',fm({'tags':['гипотезы-подход','проверка-гипотезы/завершена'],'родитель':'flyvis_temporal_residual_association_v1',
        'роль':'проверенный компонент и сильный контроль; не подтверждение Б1','исход':'связка полезна; отдельный вклад MASA-признака не изолирован'})+body)
